  const svg = (path) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
  const CARD_CONTROLS = Object.freeze({
    'Online payments': { key: 'nova_card_online_payments', defaultOn: true },
    'Contactless': { key: 'nova_card_contactless', defaultOn: true },
    'Cash withdrawals': { key: 'nova_card_cash_withdrawals', defaultOn: true },
    'Magstripe': { key: 'nova_card_magstripe', defaultOn: false }
  });
  const CARD_FROZEN_KEY = 'nova_card_frozen';
  const CARD_LIMIT_KEY = 'nova_card_daily_limit';
  const CARD_LIMIT_DEFAULT = 1200;

  function storageGet(key, fallback = '') { try { return localStorage.getItem(key) ?? fallback; } catch { return fallback; } }
  function storageSet(key, value) { try { localStorage.setItem(key, String(value)); } catch {} }
  function cardPreference(name) { const config = CARD_CONTROLS[name]; if (!config) return false; return storageGet(config.key, config.defaultOn ? 'true' : 'false') === 'true'; }
  function cardFrozen() { return storageGet(CARD_FROZEN_KEY, 'false') === 'true'; }
