  function syncCardOverviewControls() {
    if (screen !== 'cards') return;
    const frozen = cardFrozen();
    const freeze = $('[data-v3-freeze]');
    const state = $('[data-v3-card-state]');
    if (state) state.textContent = frozen ? '● Frozen' : '● Active';
    if (freeze) { freeze.dataset.frozen = String(frozen); freeze.setAttribute('aria-pressed', String(frozen)); const strong = $('strong', freeze); const note = $('span', freeze); if (strong) strong.textContent = frozen ? 'Unfreeze card' : 'Freeze card'; if (note) note.textContent = frozen ? 'Restore your saved payment preferences' : 'Pause new payments instantly'; }
    document.querySelectorAll('[data-v3-toggle]').forEach((button) => { const name = button.dataset.v3Toggle; if (!CARD_CONTROLS[name]) return; const enabled = cardPreference(name); button.dataset.enabled = String(enabled); button.setAttribute('aria-pressed', String(enabled)); button.disabled = frozen; button.setAttribute('aria-disabled', String(frozen)); const status = $('span', button); if (status) status.textContent = frozen ? `${enabled ? 'Saved on' : 'Saved off'} · blocked` : enabled ? 'Enabled' : 'Disabled'; button.title = frozen ? 'Card is frozen. This saved preference will apply again after unfreezing.' : ''; });
    const daily = $('[data-v3-daily-limit]'); if (daily) daily.textContent = formattedMoney(savedDailyLimit());
  }

  const renderers = { cards: renderCards, savings: renderSavings, security: renderSecurity, settings: renderSettings };
  const renderer = renderers[screen];
  if (renderer) { const stage = $('.app-stage'); const oldMain = $('#main'); if (stage && oldMain) oldMain.outerHTML = renderer(); document.title = `Nova — ${screen[0].toUpperCase()}${screen.slice(1)}`; }
  repairChrome();
  syncCardOverviewControls();

