    const freeze = event.target.closest('[data-v3-freeze]'); if (freeze) { const nextFrozen = !cardFrozen(); storageSet(CARD_FROZEN_KEY, nextFrozen); syncCardOverviewControls(); toast(nextFrozen ? 'Card frozen. New card payments and ATM withdrawals are blocked.' : 'Card unfrozen. Your saved payment preferences are active again.'); return; }
    const toggle = event.target.closest('[data-v3-toggle]'); if (toggle) { const name = toggle.dataset.v3Toggle; const config = CARD_CONTROLS[name]; if (!config) return; if (cardFrozen()) { syncCardOverviewControls(); toast('Card is frozen. Unfreeze before changing payment preferences.'); return; } const next = !cardPreference(name); storageSet(config.key, next); syncCardOverviewControls(); toast(`${name} ${next ? 'enabled' : 'disabled'}. This preference will be kept when you return.`); return; }
